/* Camino's stairway: each book is a step, each landing opens the next chapter. */
let caminoViewedTerm=0;
function caminoWorld(count=6){count=Math.max(1,count);const dx=(count-6)*75,dy=(count-6)*48;return `<div class="camino-world stair-world" aria-hidden="true"><div class="stair-halo"></div><svg viewBox="0 0 ${700+Math.max(0,dx)} ${500+Math.max(0,dy)}" data-stair-count="${count}" data-base-y="${350+dy}" class="stair-illustration"><defs><linearGradient id="stairTop" x2="1" y2="1"><stop stop-color="#ded2ff"/><stop offset="1" stop-color="#9380c5"/></linearGradient><linearGradient id="stairFront" x2="0" y2="1"><stop stop-color="#74618f"/><stop offset="1" stop-color="#332c48"/></linearGradient><linearGradient id="doorGlow" x2="0" y2="1"><stop stop-color="#f6d6ad"/><stop offset="1" stop-color="#d5b8f0"/></linearGradient></defs><ellipse cx="${356+dx/2}" cy="${440+dy}" rx="${260+Math.max(0,dx)/2}" ry="30" fill="#080713" opacity=".5"/>${Array.from({length:count},(_,i)=>{const x=85+i*75,y=385+dy-i*48;return `<g class="illustrated-step" style="--step:${i}"><path d="M${x} ${y}l50 -22 76 24 -50 24Z" fill="url(#stairTop)"/><path d="M${x} ${y}l76 26v${40+i*8}l-76 -25Z" fill="url(#stairFront)"/><path d="M${x+76} ${y+26}l50 -24v${40+i*8}l-50 24Z" fill="#30273f"/><path d="M${x+6} ${y+9}l63 22" stroke="#ddd0ee" stroke-width="2" opacity=".6"/><text x="${x+28}" y="${y+27}" fill="#d6c4e9" font-size="11" font-family="sans-serif">0${i+1}</text></g>`}).join('')}<g class="stair-destination" transform="translate(${dx},0)"><path d="M525 147V56Q525 20 553 31L592 44V168Z" fill="#3d3154" stroke="#c4a3df" stroke-width="2"/><path d="M535 146V61Q535 36 552 43L581 53V162Z" fill="url(#doorGlow)"/><path d="M535 146l-68 34 44 14 70 -32Z" fill="#d6b4ee" opacity=".13"/><path d="M541 96l17 6 17 -6v26l-17 6 -17 -6Z" fill="#725877"/><path d="M558 102v26" stroke="#e8d2ed"/></g><g class="stair-climber" style="transform:translate(120px,${350+dy}px)"><ellipse cx="0" cy="20" rx="15" ry="6" fill="#12101e" opacity=".4"/><circle cx="0" cy="-19" r="8" fill="#f2ceb7"/><path d="M-7 -9Q0 -14 8 -8l4 19 -21 0Z" fill="#8ce2cc"/><path d="M-5 10l-5 13M5 10l7 13" stroke="#d9c4f0" stroke-width="5" stroke-linecap="round"/><path d="M8 -4l10 6" stroke="#f2ceb7" stroke-width="4" stroke-linecap="round"/><path d="M-11 -7l-5 2v15l8 1Z" fill="#bd88c2"/></g><path class="stair-light" d="${Array.from({length:count},(_,i)=>(i?'L':'M')+(115+i*75)+' '+(402+dy-i*48)).join('')}" fill="none" stroke="#99e1d3" stroke-width="2" stroke-dasharray="3 8" opacity=".65"/></svg><span class="stair-caption">ONE STEP. A NEW CHAPTER.</span></div>`}
function animateCaminoClimb(index,total){
 document.querySelectorAll('.stair-climber').forEach(el=>{const svg=el.closest('svg'),position=Math.min(+svg.dataset.stairCount-1,index),base=+svg.dataset.baseY;el.style.transform=`translate(${120+position*75}px,${base-position*48}px)`});
 document.querySelectorAll('.illustrated-step').forEach((el,i)=>el.classList.toggle('step-reached',i<=index));
}
function bindVisualWorld(){
 document.querySelectorAll('[data-toggle-motion]').forEach(el=>el.onclick=()=>{state.reduceMotion=!state.reduceMotion;save();render()});
 const total=window.currentPlan?.length?Math.max(...currentPlan.map(c=>c.term))+1:1;
 animateCaminoClimb(caminoViewedTerm,total);
 document.querySelectorAll('[data-climb-term]').forEach(el=>el.onclick=()=>{caminoViewedTerm=+el.dataset.climbTerm;const oldY=window.scrollY;render();window.scrollTo(0,oldY);const current=document.querySelector('.stair-climber');if(current&&!state.reduceMotion&&!window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches){const previous=Math.max(0,+el.dataset.fromTerm||0),start=previous,end=caminoViewedTerm,base=+current.closest('svg').dataset.baseY;if(current.animate)current.animate([{transform:`translate(${120+start*75}px,${base-start*48}px)`},{transform:`translate(${120+(start+end)/2*75}px,${base-(start+end)/2*48-18}px)`},{transform:`translate(${120+end*75}px,${base-end*48}px)`}],{duration:700,easing:'cubic-bezier(.22,.7,.3,1)'});}document.querySelector('[data-selected-landing]')?.focus({preventScroll:true})});
}
